<?php
require_once __DIR__.'/include/config.php'; hms_start_session(); $role=(string)($_SESSION['role']??''); if(!in_array($role,['patient','doctor','admin'],true)) { http_response_code(403); exit('Sign in required.'); } hms_require_role($role); require_once __DIR__.'/include/appointments.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0; $sql='SELECT a.*,u.fullName AS patientName,d.doctorName,d.specilization FROM appointment a JOIN users u ON u.id=a.userId JOIN doctors d ON d.id=a.doctorId WHERE a.id=?';$params=[$id];if($role==='patient'){$sql.=' AND a.userId=?';$params[]=(int)$_SESSION['id'];}elseif($role==='doctor'){$sql.=' AND a.doctorId=?';$params[]=(int)$_SESSION['id'];}$res=hms_db_query($con,$sql.' LIMIT 1',$params);$appointment=$res?$res->fetch_assoc():null;if(!$appointment){http_response_code(404);exit('Appointment not found.');}
$events=hms_db_query($con,'SELECT * FROM appointment_events WHERE appointmentId=? ORDER BY createdAt DESC',[$id]);$requests=hms_db_query($con,"SELECT * FROM appointment_reschedule_requests WHERE appointmentId=? AND status='pending' ORDER BY createdAt DESC",[$id]);$base=$role==='admin'?'admin/':($role==='doctor'?'doctor':'');$back=$role==='admin'?'admin/appointment-history.php':($role==='doctor'?'doctor/appointment-history.php':'appointment-history.php');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Appointment details | MedTech</title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"><link rel="stylesheet" href="assets/css/styles.css"><link rel="stylesheet" href="assets/css/plugins.css"><link rel="stylesheet" href="assets/css/themes/theme-1.css" /><link rel="stylesheet" href="assets/css/medtech-app.css"><style>.detail-card{background:#fff;padding:24px;margin:22px auto;max-width:900px}.detail-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.detail-item{padding:12px;background:#f6f8fa;border-radius:5px}.hms-status{padding:4px 9px;border-radius:14px}.hms-status-pending{background:#fff2cc}.hms-status-confirmed{background:#d9f3e4}.hms-status-completed{background:#dbeafe}.hms-status-cancelled,.hms-status-rejected{background:#fee2e2}</style></head><body><nav class="container" style="padding:18px 0"><a href="<?=hms_h($back)?>">Appointment list</a> · <a href="<?=($role==='admin'?'admin/dashboard.php':($role==='doctor'?'doctor/dashboard.php':'dashboard.php'))?>">Dashboard</a></nav><main class="container"><div class="detail-card"><?php if(!empty($_SESSION["msg"])):?><div class="alert alert-info"><?=hms_h($_SESSION["msg"])?></div><?php unset($_SESSION["msg"]);endif;?><a href="<?=hms_h($back)?>">← Appointment list</a><h2>Appointment #<?=hms_h($id)?></h2><p><?=hms_appointment_status_badge((string)$appointment['status'])?></p><div class="detail-grid"><?php foreach(['Patient'=>'patientName','Doctor'=>'doctorName','Specialization'=>'specilization','Date'=>'appointmentDate','Time'=>'appointmentTime','Fee'=>'consultancyFees','Created'=>'postingDate'] as $label=>$key):?><div class="detail-item"><strong><?=hms_h($label)?></strong><br><?=hms_h($appointment[$key])?></div><?php endforeach;?></div><h3>Visit reason</h3><p><?=nl2br(hms_h($appointment['visitReason']??''))?:'Not provided'?></p><h3>Doctor notes</h3><p><?=nl2br(hms_h($appointment['doctorNotes']??''))?:'No notes yet'?></p>
<?php if($role==='patient'&&$appointment['status']==='confirmed'):?><h3>Request a reschedule</h3><form method="post" action="appointment-action.php" id="reschedule-form"><?=hms_csrf_field()?><input type="hidden" name="action" value="reschedule"><input type="hidden" name="appointment_id" value="<?=hms_h($id)?>"><input type="hidden" name="return_details" value="1"><div class="form-group"><label>Date</label><input type="date" id="new-date" name="date" min="<?=date('Y-m-d')?>" class="form-control" required></div><div class="form-group"><label>Available time</label><select id="new-time" name="time" class="form-control" required><option value="">Choose a date first</option></select></div><div class="form-group"><label>Note (optional)</label><input name="notes" maxlength="1000" class="form-control"></div><button class="btn btn-primary">Send reschedule request</button></form><?php endif;?>
<?php if(in_array($role,['doctor','admin'],true)&&$requests&&$requests->num_rows):?><h3>Pending reschedule requests</h3><?php while($request=$requests->fetch_assoc()):?><p>Requested <?=hms_h($request['requestedDate'])?> at <?=hms_h($request['requestedTime'])?> <?=hms_h($request['requestNote'])?></p><?php foreach(['approve'=>'Approve','reject'=>'Decline'] as $decision=>$label):?><form class="hms-inline-form" method="post" action="appointment-action.php"><?=hms_csrf_field()?><input type="hidden" name="action" value="review"><input type="hidden" name="request_id" value="<?=hms_h($request['id'])?>"><input type="hidden" name="appointment_id" value="<?=hms_h($id)?>"><input type="hidden" name="return_details" value="1"><input type="hidden" name="decision" value="<?=hms_h($decision)?>"><button class="btn btn-default"><?=hms_h($label)?></button></form><?php endforeach;endwhile;endif;?>
<?php if($role==='doctor'||$role==='admin'):?><h3>Update status</h3><form method="post" action="appointment-action.php"><?=hms_csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="appointment_id" value="<?=hms_h($id)?>"><input type="hidden" name="return_details" value="1"><div class="form-group"><select name="status" class="form-control" required><?php $choices=$role==='doctor'?['confirmed'=>'Confirm','rejected'=>'Reject','completed'=>'Complete']:['confirmed'=>'Confirm','cancelled'=>'Cancel','rejected'=>'Reject','completed'=>'Complete'];foreach($choices as $value=>$label):?><option value="<?=hms_h($value)?>"><?=hms_h($label)?></option><?php endforeach;?></select></div><div class="form-group"><label>Visit notes (optional)</label><textarea name="notes" maxlength="1000" class="form-control"></textarea></div><button class="btn btn-primary">Save status</button></form><?php endif;?>
<h3>Appointment activity</h3><ul><?php while($event=$events->fetch_assoc()):?><li><?=hms_h($event['createdAt'])?> — <?=hms_h(str_replace('_',' ',$event['eventType']))?><?php if($event['notes']):?>: <?=hms_h($event['notes'])?><?php endif;?></li><?php endwhile;?></ul></div></main>
<script>const d=document.getElementById('new-date');if(d)d.addEventListener('change',async()=>{const t=document.getElementById('new-time');t.innerHTML='<option>Loading…</option>';try{const r=await fetch('available-slots.php?doctor_id=<?=hms_h($appointment['doctorId'])?>&date='+encodeURIComponent(d.value)+'&exclude_id=<?=hms_h($id)?>'),j=await r.json();t.innerHTML='<option value="">Choose available time</option>';for(const s of j.slots||[]){const o=document.createElement('option');o.value=s.value;o.textContent=s.label;t.append(o);}if(!j.slots?.length)t.innerHTML='<option value="">No times available</option>';}catch(e){t.innerHTML='<option value="">Could not load times</option>';}});</script></body></html>
